import io
import json
import os
from typing import Any, Dict, List, Optional, Union

import boto3
from botocore.client import Config


def _load_document_bytes(document: Union[str, bytes, bytearray, io.IOBase]) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    if isinstance(document, str):
        if document.startswith("s3://"):
            s3 = boto3.client("s3")
            bucket_key = document[5:]
            bucket, _, key = bucket_key.partition("/")
            if not bucket or not key:
                raise ValueError("Invalid S3 URI. Expected format: s3://bucket/key")
            obj = s3.get_object(Bucket=bucket, Key=key)
            return obj["Body"].read()
        with open(document, "rb") as f:
            return f.read()
    if hasattr(document, "read"):
        data = document.read()
        if isinstance(data, str):
            data = data.encode("utf-8")
        return data
    raise TypeError("document must be bytes, bytearray, file-like object, local path, or s3:// URI")


def _normalize_blocks(blocks: List[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    return {block["Id"]: block for block in blocks if "Id" in block}


def _extract_text_from_relationship(block: Dict[str, Any], id_to_block: Dict[str, Dict[str, Any]]) -> str:
    texts: List[str] = []
    for rel in block.get("Relationships", []):
        if rel.get("Type") != "CHILD":
            continue
        for child_id in rel.get("Ids", []):
            child = id_to_block.get(child_id, {})
            if child.get("BlockType") == "WORD":
                txt = child.get("Text", "")
                if txt:
                    texts.append(txt)
            elif child.get("BlockType") == "SELECTION_ELEMENT":
                if child.get("SelectionStatus") == "SELECTED":
                    texts.append("X")
    return " ".join(texts).strip()


def _extract_cells_and_rows(textract_response: Dict[str, Any]) -> Dict[str, Any]:
    blocks = textract_response.get("Blocks", [])
    id_to_block = _normalize_blocks(blocks)

    tables: List[Dict[str, Any]] = []
    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        cells = []
        row_map: Dict[int, Dict[int, Dict[str, Any]]] = {}
        for rel in block.get("Relationships", []):
            if rel.get("Type") != "CHILD":
                continue
            for cell_id in rel.get("Ids", []):
                cell = id_to_block.get(cell_id)
                if not cell or cell.get("BlockType") != "CELL":
                    continue
                row_index = int(cell.get("RowIndex", 0))
                col_index = int(cell.get("ColumnIndex", 0))
                text = _extract_text_from_relationship(cell, id_to_block)
                cell_record = {
                    "row_index": row_index,
                    "column_index": col_index,
                    "row_span": int(cell.get("RowSpan", 1)),
                    "column_span": int(cell.get("ColumnSpan", 1)),
                    "text": text,
                    "confidence": cell.get("Confidence"),
                    "geometry": cell.get("Geometry"),
                }
                cells.append(cell_record)
                row_map.setdefault(row_index, {})[col_index] = cell_record

        rows: List[Dict[str, Any]] = []
        for row_index in sorted(row_map):
            row_cells = [row_map[row_index][col] for col in sorted(row_map[row_index])]
            rows.append(
                {
                    "row_index": row_index,
                    "cells": row_cells,
                    "texts": [c["text"] for c in row_cells],
                }
            )

        tables.append(
            {
                "cells": sorted(cells, key=lambda x: (x["row_index"], x["column_index"])),
                "rows": rows,
            }
        )

    return {"tables": tables, "raw_response": textract_response}


def extract_table_cells_and_rows(
    document: Union[str, bytes, bytearray, io.IOBase],
    *,
    region_name: Optional[str] = None,
    aws_profile: Optional[str] = None,
    analyze_feature_types: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """
    Extract table cells and row structure from a document using Amazon Textract.

    Args:
        document: Local file path, s3:// URI, bytes, or file-like object.
        region_name: Optional AWS region name.
        aws_profile: Optional AWS profile name.
        analyze_feature_types: Optional Textract feature types; defaults to ["TABLES"].

    Returns:
        Dict with extracted tables, each containing cells and row structure.
    """
    feature_types = analyze_feature_types or ["TABLES"]
    document_bytes = _load_document_bytes(document)

    session_kwargs = {}
    if aws_profile:
        import boto3.session

        session_kwargs["profile_name"] = aws_profile
        session = boto3.session.Session(**session_kwargs)
        client = session.client("textract", region_name=region_name, config=Config(retries={"max_attempts": 5, "mode": "standard"}))
    else:
        client = boto3.client(
            "textract",
            region_name=region_name,
            config=Config(retries={"max_attempts": 5, "mode": "standard"}),
        )

    response = client.analyze_document(Document={"Bytes": document_bytes}, FeatureTypes=feature_types)
    return _extract_cells_and_rows(response)
